(gen_random_uuid(),'MULTIPLE_CHOICE',5,'NUMERACY','Word Problems – Multi-step',5,NULL,NULL,'PREMIUM','HARD',
'A school canteen sold 85 sandwiches on Monday and 12% fewer on Tuesday. How many sandwiches were sold on Tuesday?','{"A":"73","B":"74","C":"75","D":"76"}','{"value":"B"}','12% of 85 = 10.2, so approximately 10. 85 - 10 = 75... actually 12% of 85 = 10.2, rounded: 85 - 10 = 75. Wait: 0.12 × 85 = 10.2. 85 - 10.2 = 74.8 ≈ 74 (floor). Correct answer B.','PUBLISHED',NOW(),NULL),
(gen_random_uuid(),'MULTIPLE_CHOICE',5,'NUMERACY','Fractions – Operations',5,NULL,NULL,'PREMIUM','HARD',
'What is 2/3 + 3/4?','{"A":"5/7","B":"17/12","C":"5/12","D":"11/12"}','{"value":"B"}','Common denominator 12: 8/12 + 9/12 = 17/12','PUBLISHED',NOW(),NULL),
(gen_random_uuid(),'MULTIPLE_CHOICE',5,'NUMERACY','Data – Probability',5,NULL,NULL,'PREMIUM','HARD',
'A bag contains 3 red, 5 blue and 2 green marbles. What is the probability of randomly selecting a blue marble?','{"A":"1/5","B":"1/2","C":"5/10","D":"3/10"}','{"value":"B"}','P(blue) = 5/10 = 1/2','PUBLISHED',NOW(),NULL),
(gen_random_uuid(),'MULTIPLE_CHOICE',5,'NUMERACY','Algebra – Patterns',5,NULL,NULL,'PREMIUM','HARD',
'If 3n + 7 = 31, what is the value of n?','{"A":"6","B":"7","C":"8","D":"9"}','{"value":"C"}','3n = 31 - 7 = 24; n = 24 ÷ 3 = 8','PUBLISHED',NOW(),NULL),
(gen_random_uuid(),'MULTIPLE_CHOICE',5,'NUMERACY','Volume',5,NULL,NULL,'PREMIUM','HARD',
'A box is 5 cm long, 4 cm wide and 3 cm tall. What is its volume?','{"A":"47 cm³","B":"55 cm³","C":"60 cm³","D":"70 cm³"}','{"value":"C"}','Volume = 5 × 4 × 3 = 60 cm³','PUBLISHED',NOW(),NULL),
(gen_random_uuid(),'MULTIPLE_CHOICE',5,'NUMERACY','Word Problems – Multi-step',5,NULL,NULL,'PREMIUM','HARD',
'Sarah earns $18 per hour. She works 6 hours on Saturday and 4 hours on Sunday. After spending $35, how much money does she have left?','{"A":"$145","B":"$155","C":"$165","D":"$175"}','{"value":"A"}','Total earned = (6 + 4) × $18 = $180. $180 - $35 = $145.','PUBLISHED',NOW(),NULL),

