'Which sentence contains an ambiguous pronoun reference?','{"A":"Sam told the teacher that the teacher was wrong.","B":"Sam told the teacher that he was wrong.","C":"The teacher was wrong, as Sam pointed out.","D":"Sam pointed out the teacher''s error."}','{"value":"B"}','"he" could refer to either Sam or the teacher, creating ambiguity.','PUBLISHED',NOW(),NULL),
(gen_random_uuid(),'MULTIPLE_CHOICE',5,'GRAMMAR_PUNCTUATION','Voice',5,NULL,NULL,'PREMIUM','HARD',
'Rewrite the following in the active voice: "The report was submitted by the committee." Which option is correct?','{"A":"The committee submits the report.","B":"The committee submitted the report.","C":"The report has been submitted.","D":"The committee will submit the report."}','{"value":"B"}','The active voice version uses the committee as the subject performing the action in past tense.','PUBLISHED',NOW(),NULL),
